with base as (select id, customer_id, account_type, opened_date, status, cast(balance as int) as balance_int, concat(account_type, '/', status) as account_type_status, coalesce(status, 'NONE') as status_clean from accounts where status is not null and opened_date >= to_date('2023-06-20')) select *, row_number() over w_running as row_seq, ntile(5) over (partition by customer_id order by balance_int desc, id) as balance_int_bucket, lead(balance_int, 2, 0) over (partition by status order by balance_int, id) as next_balance_int, avg(balance_int) over (partition by account_type, customer_id order by opened_date, id rows between 3 preceding and current row) as balance_int_avg_3 from base window w_running as (partition by status, customer_id order by balance_int, id)
